def params_to_normal_form(params, offsets):
    return _k.fcall(6019, params, offsets)

def intersect_3_planes(p1, p2, p3):
    a = np.array([p1[0:3], p2[0:3], p3[0:3]])
    b = np.array([p1[3], p2[3], p3[3]])
    sol = np.linalg.solve(a, b)
    return sol

